#include <bits/stdc++.h>
using namespace std;static const int P=32719;int mod(long long x){x%=P;if(x<0)x+=P;return x;}int mul(int a,int b){return (long long)a*b%P;}int pw(int a,int e){int r=1;while(e){if(e&1)r=mul(r,a);a=mul(a,a);e>>=1;}return r;}vector<int>conv(const vector<int>&a,const vector<int>&b){vector<int>c(a.size()+b.size()-1);for(int i=0;i<(int)a.size();i++)for(int j=0;j<(int)b.size();j++)c[i+j]=mod(c[i+j]+(long long)a[i]*b[j]);return c;}vector<int>poly_power(vector<int>a,int n){vector<int>x{1};while(n){if(n&1)x=conv(x,a);n>>=1;if(n)a=conv(a,a);}return x;}int choosei(int n,int k){if(k<0||k>n)return 0;long long x=1;for(int i=1;i<=k;i++)x=x*(n+1-i)/i;return x%P;}
int main(int argc,char**argv){if(argc!=3)throw runtime_error("gates ranks");int q=8,K=(q-2)*(q-2)+1;vector<pair<int,int>>mons;for(int b=q-3;b>=0;b--)for(int a=2*q-6-2*b;a>=0;a--)mons.push_back({a,b});vector<vector<int>>Lag;for(int r=3;r<=8;r++){vector<int>x{1};int den=1;for(int s=3;s<=8;s++)if(s!=r){x=conv(x,{mod(-s),1});den=mod((long long)den*(r-s));}int iv=pw(den,P-2);for(int&v:x)v=mul(v,iv);Lag.push_back(x);}map<array<int,4>,pair<vector<int>,vector<int>>>cache;
 auto coeff=[&](const vector<int>&npart,int b,int r,int v,int shear,int i,int j){if(j>b)return 0;auto xp=poly_power({v,shear},b-j);long long z=0;for(int t=0;t<(int)npart.size();t++)if(i-t>=0&&i-t<(int)xp.size())z+=(long long)npart[t]*xp[i-t]%P;return mod(z*choosei(b,j));};
 auto row=[&](int r,int s,int i,int j)->pair<vector<int>,vector<int>>&{array<int,4>key{r,s,i,j};auto it=cache.find(key);if(it!=cache.end())return it->second;auto&out=cache[key];int v=s*(r-s),sh=(2*s==r?s:0);vector<int>W{1};for(int t=3;t<=8;t++)W=conv(W,{mod(r-t),1});for(auto[a,b]:mons){auto n=conv(W,poly_power({r,1},a));out.first.push_back(coeff(n,b,r,v,sh,i,j));}for(int b=0;b<=q;b++)for(int a=0;a<6;a++)out.second.push_back(coeff(poly_power({r,1},a),b,r,v,sh,i,j));return out;};
 ifstream gates(argv[1]),ranks(argv[2]);string gs,rs;int count=0,inv5=pw(5,P-2);while(getline(gates,gs)){if(!getline(ranks,rs))throw runtime_error("missing rank");istringstream gi(gs),ri(rs);int qq,z,A;long long Pnum;gi>>qq>>z>>A>>Pnum;if(qq!=8)throw runtime_error("q");vector<vector<int>>m(6);for(int r=3;r<=8;r++){m[r-3].resize(r/2+1);for(int&x:m[r-3])gi>>x;}vector<int>H0(6*(q+1));for(int r=3;r<=8;r++){vector<int>pr{1};for(int s=0;s<=r/2;s++)for(int j=0;j<m[r-3][s];j++)pr=conv(pr,{mod(-s*(r-s)),1});if(r==7)pr=conv(pr,{mul(mod(Pnum),inv5),mod(-A),1});if((int)pr.size()!=q+1)throw runtime_error("row degree");for(int b=0;b<=q;b++)for(int a=0;a<6;a++)H0[6*b+a]=mod(H0[6*b+a]+(long long)pr[b]*Lag[r-3][a]);}
 int id,nrank,olddet;ri>>id>>nrank>>olddet;if(id!=count||nrank!=K||olddet==0)throw runtime_error("rank header");vector<vector<int>>Mat;set<int>ids;int rid;while(ri>>rid){if(!ids.insert(rid).second)throw runtime_error("dup jet");int r=rid/100000,rem=rid%100000,s=rem/10000;rem%=10000;int i=rem/100,j=rem%100;if(r<3||r>8||s<0||s>r/2||i<1)throw runtime_error("id");int mm=m[r-3][s];if((2*s==r ? i+2*j>=2*mm : i+j>=mm))throw runtime_error("nonnecessary");auto&R=row(r,s,i,j);auto v=R.first;long long rhs=0;for(int t=0;t<(int)H0.size();t++)rhs+=(long long)H0[t]*R.second[t]%P;v.push_back(mod(rhs));Mat.push_back(v);}if((int)Mat.size()!=K)throw runtime_error("dim");int det=1;for(int c=0;c<K;c++){int piv=K-1;while(piv>=c&&!Mat[piv][c])piv--;if(piv<c)throw runtime_error("zero det");if(piv!=c){swap(Mat[c],Mat[piv]);det=mod(-det);}int v=Mat[c][c];det=mul(det,v);int iv=pw(v,P-2);for(int j=c;j<K;j++)Mat[c][j]=mul(Mat[c][j],iv);for(int r=c+1;r<K;r++)if(Mat[r][c]){int f=Mat[r][c];for(int j=c;j<K;j++)Mat[r][j]=mod(Mat[r][j]-(long long)f*Mat[c][j]);}}if(det!=olddet&&det!=mod(-olddet))throw runtime_error("det mismatch");count++;}
 string extra;if(getline(ranks,extra))throw runtime_error("extra ranks");cout<<"PASS_Q8_2DELTA7_LOCAL_MINORS count="<<count<<" modulus="<<P<<"\n";}
